nonisolated final class AgentWorkflowMonitor: @unchecked Sendable {
    static let shared = AgentWorkflowMonitor()

    private let lock = NSLock()
    private var observerID: UUID?
    private var events: [AgentWorkflowEvent] = []
    private let maxEvents: Int

    var isMonitoring: Bool {
        lock.lock()
        defer { lock.unlock() }
        return observerID != nil
    }

    init(maxEvents: Int = 500, startObserving: Bool = false) {
        self.maxEvents = max(10, maxEvents)
        if startObserving {
            _ = start()
        }
    }

    deinit {
        stop()
    }

    @discardableResult
    func start() -> Bool {
        lock.lock()
        defer { lock.unlock() }
        guard observerID == nil else { return false }

        let id = PersistentRuntimeDiagnosticsObserver.shared.addObserver { [weak self] signal in
            self?.ingest(signal)
        }
        observerID = id
        return true
    }

    func stop() {
        let id: UUID?
        lock.lock()
        id = observerID
        observerID = nil
        lock.unlock()
        if let id {
            PersistentRuntimeDiagnosticsObserver.shared.removeObserver(id)
        }
    }

    func reset() {
        lock.lock()
        events.removeAll()
        lock.unlock()
    }

    func ingestForTests(_ signal: PersistentRuntimeDiagnosticSignal) {
        ingest(signal)
    }

    func ingest(_ signal: PersistentRuntimeDiagnosticSignal) {
        guard let event = Self.event(from: signal) else { return }
        lock.lock()
        events.append(event)
        if events.count > maxEvents {
            events.removeFirst(events.count - maxEvents)
        }
        lock.unlock()","language":"swift","lineEnd":221,"lineStart":142,"module":"Diagnostics","path":"ios/Lumen/Diagnostics/AgentWorkflowMonitor.swift","sourceHash":"84d4b962ef3fa46e44b1d2c6df93b978558193abdeb33d816a64d611518de2c8"}

